const menu = document.querySelector('.menu');
const navigation = document.querySelector('#navigation');
menu.addEventListener('click', () => { const open = menu.getAttribute('aria-expanded') !== 'true'; menu.setAttribute('aria-expanded', String(open)); navigation.classList.toggle('open', open); });
navigation.querySelectorAll('a').forEach(link => link.addEventListener('click', () => { menu.setAttribute('aria-expanded', 'false'); navigation.classList.remove('open'); }));
document.addEventListener('keydown', event => { if(event.key === 'Escape' && menu.getAttribute('aria-expanded') === 'true'){menu.setAttribute('aria-expanded','false');navigation.classList.remove('open');menu.focus();} });
document.querySelector('#year').textContent = new Date().getFullYear();
document.querySelector('#enquiry-form').addEventListener('submit', event => { event.preventDefault(); const data = new FormData(event.currentTarget); const subject = `Commercial enquiry — ${data.get('interest')} — ${data.get('company')}`; const body = `Name: ${data.get('name')}\nCompany: ${data.get('company')}\nEmail: ${data.get('email')}\nArea of interest: ${data.get('interest')}\n\nRequirements:\n${data.get('message')}`; window.location.href = `mailto:info@nbkdiesel.com?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`; document.querySelector('#form-status').textContent = 'Your email app has been requested. Review and send your enquiry there. If it does not open, email info@nbkdiesel.com directly.'; });
